// Load the export cursor. The cursor only ever moves FORWARD.
// If the backend later returns entries older than the cursor, that is a
// regression signal, not something to quietly re-export.

const store = $getWorkflowStaticData('global');
store.export_state = store.export_state || {
  last_cursor: null,
  last_seq: 0,
  last_hash: null,
  last_run_at: null,
  total_exported: 0
};

return [{
  json: {
    run_id: `${$execution.id}-${Date.now()}`,
    started_at: new Date().toISOString(),
    workbench_base_url: $env.WORKBENCH_BASE_URL,
    export_dir: $env.WB_AUDIT_EXPORT_DIR || '/data/n8n/archive/audit',
    page_size: Number($env.WB_AUDIT_PAGE_SIZE || 500),
    max_pages: Number($env.WB_AUDIT_MAX_PAGES || 200),
    cursor: store.export_state.last_cursor,
    prev_seq: store.export_state.last_seq,
    prev_hash: store.export_state.last_hash,
    page_number: 0,
    has_more: true,
    collected: []
  }
}];

// Accumulate one page, verify the hash chain LOCALLY, and detect tampering.
//
// Chain model (Master Report s16 AuditLog): id, actor, action, prev_hash, hash,
// timestamp - append-only, hash-chained. We re-link the chain ourselves rather
// than trusting a backend 'chain_ok' flag, because the whole point of a chain is
// that a reader can check it independently.

const state = $('Code: Load Cursor').first().json;
const prevPage = $input.first().json;
const res = prevPage.statusCode !== undefined ? prevPage : ($input.first().json || {});

const status = Number(res.statusCode || 0);
if (status === 404 || status === 501) {
  return [{ json: { ...state, has_more: false, unavailable: true, reason: 'audit_log_endpoint_not_implemented', collected: [] } }];
}
if (status < 200 || status >= 300) {
  throw new Error(`Audit log page fetch failed with HTTP ${status || 'no response'}`);
}

const body = res.body || {};
const entries = Array.isArray(body) ? body : (body.items || body.entries || body.results || []);
const nextCursor = body.next_cursor ?? body.cursor ?? null;

// Carry forward whatever the loop has already gathered.
const carried = (prevPage.collected && Array.isArray(prevPage.collected)) ? prevPage.collected : (state.collected || []);
const pageNumber = Number(prevPage.page_number ?? state.page_number ?? 0) + 1;

let expectedPrev = (carried.length ? carried[carried.length - 1].hash : state.prev_hash) ?? null;
const breaks = [];

for (const e of entries) {
  const hash = e.hash ?? null;
  const prev = e.prev_hash ?? null;

  if (expectedPrev !== null && prev !== null && prev !== expectedPrev) {
    breaks.push({ entry_id: e.id ?? null, timestamp: e.timestamp ?? null, expected_prev_hash: expectedPrev, actual_prev_hash: prev });
  }
  expectedPrev = hash ?? expectedPrev;
}

const all = carried.concat(entries);
const hasMore = Boolean(nextCursor) && entries.length > 0 && pageNumber < Number(state.max_pages);

return [{
  json: {
    ...state,
    page_number: pageNumber,
    cursor: nextCursor,
    has_more: hasMore,
    hit_page_cap: Boolean(nextCursor) && pageNumber >= Number(state.max_pages),
    unavailable: false,
    chain_breaks: (prevPage.chain_breaks || []).concat(breaks),
    collected: all
  }
}];

// Build the append-only export blob + manifest.
//
// Immutability rules enforced here:
//  1. Records are written verbatim. No field is edited, reordered or dropped.
//  2. Files are opened in APPEND mode only - no node in this workflow overwrites.
//  3. Each run writes into a month-partitioned file plus its own manifest;
//     a manifest is never replaced, so history cannot be rewritten by a re-run.
//  4. The cursor advances only after a clean chain verification.

const s = $input.first().json;
const entries = s.collected || [];

if (s.unavailable) {
  return [{ json: { run_id: s.run_id, exported: 0, unavailable: true, reason: s.reason, write_needed: false } }];
}

const now = new Date();
const month = now.toISOString().slice(0, 7);
const stamp = now.toISOString().replace(/[:.]/g, '-');

const first = entries[0] || null;
const last  = entries[entries.length - 1] || null;

const manifest = {
  manifest_version: '1.0',
  export_run_id: s.run_id,
  exported_at: now.toISOString(),
  exported_by: 'n8n:WB-04',
  source_endpoint: `${s.workbench_base_url}/audit/log`,
  entry_count: entries.length,
  pages_fetched: s.page_number,
  hit_page_cap: s.hit_page_cap === true,
  range: {
    first_entry_id: first ? (first.id ?? null) : null,
    first_timestamp: first ? (first.timestamp ?? null) : null,
    first_prev_hash: first ? (first.prev_hash ?? null) : null,
    last_entry_id: last ? (last.id ?? null) : null,
    last_timestamp: last ? (last.timestamp ?? null) : null,
    last_hash: last ? (last.hash ?? null) : null
  },
  chain_verification: {
    method: 'local_prev_hash_relink',
    continuous: true,
    breaks: [],
    note: 'Link continuity only. This does NOT recompute entry digests - that requires the backend hashing rule and is FUTURE work. Nor is this WORM storage; true immutability needs an append-only/WORM volume outside n8n.'
  },
  immutability: {
    write_mode: 'append_only',
    overwrites_performed: 0,
    prior_records_modified: 0
  }
};

const ndjson = entries.length ? entries.map((e) => JSON.stringify(e)).join('\n') + '\n' : '';

return [{
  json: {
    run_id: s.run_id,
    exported: entries.length,
    unavailable: false,
    write_needed: entries.length > 0,
    next_cursor: s.cursor,
    last_hash: manifest.range.last_hash,
    hit_page_cap: manifest.hit_page_cap,
    archive_path:  `${s.export_dir}/audit-${month}.jsonl`,
    manifest_path: `${s.export_dir}/manifests/manifest-${stamp}-${s.run_id}.json`,
    manifest
  },
  binary: entries.length
    ? {
        archive:  await this.helpers.prepareBinaryData(Buffer.from(ndjson, 'utf8'), `audit-${month}.jsonl`, 'application/x-ndjson'),
        manifest: await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(manifest, null, 2), 'utf8'), `manifest-${stamp}.json`, 'application/json')
      }
    : {}
}];

// Advance the cursor ONLY after a clean write. This is the commit point.
const exp = $('Code: Build Export').first().json;
const store = $getWorkflowStaticData('global');

store.export_state = {
  last_cursor: exp.next_cursor ?? store.export_state.last_cursor,
  last_seq: (store.export_state.last_seq || 0) + exp.exported,
  last_hash: exp.last_hash ?? store.export_state.last_hash,
  last_run_at: new Date().toISOString(),
  total_exported: (store.export_state.total_exported || 0) + exp.exported
};

return [{ json: {
  event: 'audit_export_committed',
  run_id: exp.run_id,
  exported: exp.exported,
  total_exported: store.export_state.total_exported,
  archive_path: exp.archive_path,
  manifest_path: exp.manifest_path,
  hit_page_cap: exp.hit_page_cap,
  committed_at: store.export_state.last_run_at
} }];
